"use client";

import { useCallback, useRef, useState } from "react";
import { verifyC2pa } from "@/lib/c2pa/browser";
import type { C2paVerificationReceipt } from "@/lib/c2pa/types";
import { inspectFile } from "@/lib/files";
import { sha256Hex } from "@/lib/files/hash";
import { buildVerificationReceipt } from "@/lib/files/verification-receipt";
import type { FileInspectionReceipt, FileSanitizeResult } from "@/lib/files";
import { isAcceptedFileKind, MAX_FILE_BYTES, validateFileSize } from "@/lib/product-contract";
import { emitReceipt } from "./receipt-drawer";
import { TurnstileWidget } from "./turnstile-widget";

const ADVANCED_MAX_BYTES = 20 * 1024 * 1024;
const ACCEPT = ".jpg,.jpeg,.png,.webp,.docx,.pdf,image/jpeg,image/png,image/webp,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document";
function messageFrom(payload: unknown, fallback: string) { if (payload && typeof payload === "object") { const error = (payload as { error?: unknown }).error;if (typeof error === "string") return error;if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") return (error as { message: string }).message; }return fallback; }

export function FileWorkbench() {
  const [file, setFile] = useState<File | null>(null);const [receipt, setReceipt] = useState<FileInspectionReceipt | null>(null);const [inspectionId,setInspectionId]=useState<string|null>(null);const [originalHash, setOriginalHash] = useState<string | null>(null);const [cleaned, setCleaned] = useState<FileSanitizeResult | null>(null);const [cleanedHash, setCleanedHash] = useState<string | null>(null);const [c2pa, setC2pa] = useState<C2paVerificationReceipt | null>(null);const [error, setError] = useState<string | null>(null);const [billingNote, setBillingNote] = useState<string | null>(null);const [busy, setBusy] = useState(false);const [c2paBusy, setC2paBusy] = useState(false);const [challengeToken, setChallengeToken] = useState<string | null>(null);const [challengeReset, setChallengeReset] = useState(0);const selectionToken = useRef(0);const onChallenge = useCallback((token: string | null) => setChallengeToken(token), []);
  async function bytesForSelected(selected: File | null = file) { if (!selected) throw new Error("Choose a file first.");const parityKind = isAcceptedFileKind(selected.name, selected.type);if (parityKind && parityKind !== "txt" && !validateFileSize(selected.size)) throw new Error("DOCX, PNG and JPEG files are limited to 3.2 MB per cleaning job.");if (!parityKind && selected.size > ADVANCED_MAX_BYTES) throw new Error("Advanced inspection-only files are limited to 20 MB.");return new Uint8Array(await selected.arrayBuffer()); }
  function publishInspection(nextReceipt:FileInspectionReceipt,hash:string,id:string){emitReceipt({id,title:"File inspection receipt",operation:"file.inspect",status:nextReceipt.summary.provenance?"review":"inspected",inputSizeBucket:formatBytes(nextReceipt.file.bytes),originalHash:hash,findingsPreserved:nextReceipt.summary.total,verification:nextReceipt.summary.provenance?"Inspection found provenance-related metadata. Sanitization remains conservative.":"Local file inspection completed.",details:[{label:"Format",value:nextReceipt.file.format.toUpperCase()},{label:"Privacy metadata",value:nextReceipt.summary.privacyMetadata},{label:"Provenance",value:nextReceipt.summary.provenance},{label:"Safe removals",value:nextReceipt.summary.removableByDefault}]});}
  async function runInspection() { if (!file) return;const selected = file;const token = selectionToken.current;setBusy(true);setError(null);setBillingNote(null);setCleaned(null);setCleanedHash(null);setC2pa(null);try { const bytes = await bytesForSelected(selected);const nextReceipt = inspectFile(bytes, selected.name);const hash = await sha256Hex(bytes);const id=crypto.randomUUID();if (token !== selectionToken.current) return;setReceipt(nextReceipt);setOriginalHash(hash);setInspectionId(id);publishInspection(nextReceipt,hash,id); } catch (cause) { if (token !== selectionToken.current) return;setReceipt(null);setOriginalHash(null);setInspectionId(null);setError(cause instanceof Error ? cause.message : "Could not inspect this file."); } finally { setBusy(false); } }
  async function runC2paVerification() { if (!file || !receipt) return;const selected = file;const token = selectionToken.current;setC2paBusy(true);setError(null);try { const next = await verifyC2pa(selected);if (token === selectionToken.current){setC2pa(next);emitReceipt({id:crypto.randomUUID(),title:"Content Credentials verification",operation:"c2pa.verify",status:next.status==="valid"?"validated":next.status==="not_present"?"inspected":"review",originalHash:originalHash??undefined,verification:next.note,details:[{label:"Status",value:formatC2paStatus(next.status)},{label:"Manifests",value:next.manifestCount},{label:"Validation statuses",value:next.validation.length}]});} } catch (cause) { if (token === selectionToken.current) setError(cause instanceof Error ? cause.message : "Could not verify Content Credentials."); } finally { setC2paBusy(false); } }
  async function runSanitize() { if (!file || !receipt || !challengeToken) return;const selected = file;const before = receipt;const token = selectionToken.current;const operationId=crypto.randomUUID();setBusy(true);setError(null);setBillingNote(null);try { const bytes = await bytesForSelected(selected);const sessionResponse = await fetch("/api/auth/anonymous", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ challengeToken, forClean: true }) });const sessionPayload = await sessionResponse.json();if (!sessionResponse.ok) throw new Error(messageFrom(sessionPayload, "Could not prepare the account for this cleaning job."));const response = await fetch("/api/files/sanitize", { method: "POST", headers: { "content-type": selected.type || "application/octet-stream", "x-file-name": encodeURIComponent(selected.name), "x-operation-id": operationId }, body: bytes });if (!response.ok) { const payload = await response.json().catch(() => null);throw new Error(messageFrom(payload, "Could not sanitize this file.")); }const output = new Uint8Array(await response.arrayBuffer());if (token !== selectionToken.current) return;const encodedOutputName = response.headers.get("x-output-file-name");let outputFileName = `${baseName(selected.name)}.clean.${selected.name.split(".").pop() ?? "file"}`;if (encodedOutputName) { try { outputFileName = decodeURIComponent(encodedOutputName); } catch {} }const after = inspectFile(output, outputFileName);const remainingIds = new Set(after.findings.map(item => item.id));const result: FileSanitizeResult = { version: "file-sanitize-v1", output, outputFileName, mimeType: response.headers.get("content-type") || before.file.mimeType, removed: before.findings.filter(item => item.removableByDefault && !remainingIds.has(item.id)), preserved: before.findings.filter(item => !item.removableByDefault || remainingIds.has(item.id)), before, after };const outHash=await sha256Hex(output);setCleaned(result);setCleanedHash(outHash);const credits = Number(response.headers.get("x-credits-charged") ?? 1);const balanceAfter = Number(response.headers.get("x-balance-after") ?? sessionPayload?.balance?.available ?? 0);setBillingNote(`${credits} credit${credits === 1 ? "" : "s"} charged · ${balanceAfter} remaining`);emitReceipt({id:operationId,title:"File sanitation receipt",operation:`${before.file.format}.sanitize`,status:"validated",accountState:sessionPayload?.isAnonymous===false?"registered":"guest",creditsReserved:credits,creditsCommitted:credits,inputSizeBucket:formatBytes(before.file.bytes),originalHash:originalHash??undefined,outputHash:outHash,findingsRemoved:result.removed.length,findingsPreserved:result.preserved.length,verification:after.summary.removableByDefault===0?"Returned bytes were re-inspected in the browser and no default-removable metadata remains.":"Returned bytes require additional review.",details:[{label:"Before privacy metadata",value:before.summary.privacyMetadata},{label:"After privacy metadata",value:after.summary.privacyMetadata},{label:"Provenance before",value:before.summary.provenance},{label:"Provenance after",value:after.summary.provenance}]});window.dispatchEvent(new Event("provenance:account-changed")); } catch (cause) { if (token === selectionToken.current) setError(cause instanceof Error ? cause.message : "Could not sanitize this file."); } finally { setBusy(false);setChallengeToken(null);setChallengeReset(value => value + 1); } }
  function downloadCleaned() { if (!cleaned) return;const copy = cleaned.output.slice();downloadBlob(new Blob([copy.buffer], { type: cleaned.mimeType }), cleaned.outputFileName); }
  function downloadReceipt() { if (!receipt || !originalHash) return;const exportable = buildVerificationReceipt({ originalHash, inspection: receipt, c2pa, cleaned, cleanedHash });downloadBlob(new Blob([JSON.stringify(exportable, null, 2)], { type: "application/json" }), `${baseName(receipt.file.name)}.verification.json`); }
  const sanitizeBlocked = !receipt || !receipt.capabilities.sanitize;const hasProvenance = Boolean(receipt?.summary.provenance);const canVerifyC2pa = Boolean(receipt && receipt.file.format !== "docx");const selectedParityKind = file ? isAcceptedFileKind(file.name, file.type) : null;

  return <section className="file-section" aria-label="File metadata scanner"><div className="section-heading"><div><p className="eyebrow">File metadata & provenance</p><h2>Inspect, verify, then decide.</h2><p>DOCX, PNG and JPEG follow the 3.2 MB parity cleaning contract. PDF and WebP remain inspection-only. Signed provenance is never silently destroyed.</p></div><span className="pill file-pill">DOCX · PNG · JPEG ≤ {(MAX_FILE_BYTES / (1024 * 1024)).toFixed(1)} MB</span></div>
    <div className="file-grid"><div className="panel file-drop-panel"><label className="drop-zone"><input type="file" accept={ACCEPT} disabled={busy || c2paBusy} onChange={(event) => { selectionToken.current += 1;const next = event.target.files?.[0] ?? null;setFile(next);setReceipt(null);setInspectionId(null);setOriginalHash(null);setCleaned(null);setCleanedHash(null);setC2pa(null);setError(null);setBillingNote(null); }} /><span className="drop-icon">↧</span><strong>{file ? file.name : "Choose a document or image"}</strong><span>{file ? `${formatBytes(file.size)} · ${selectedParityKind && selectedParityKind !== "txt" ? "1-unit cleaning job" : "advanced local inspection"}` : "DOCX · PNG · JPEG · PDF inspection · WebP inspection"}</span></label>
      {file && <div className="selected-file-card"><div><span className="mono-label">SELECTED INPUT</span><strong>{file.name}</strong></div><div><span>{selectedParityKind?.toUpperCase()??"ADVANCED"}</span><span>{formatBytes(file.size)}</span></div></div>}
      <div className="actions primary-actions"><button className="primary" disabled={!file || busy} onClick={runInspection}>{busy ? "Working…" : "Inspect file"}</button><button className="secondary" disabled={!file || busy || sanitizeBlocked || !challengeToken} onClick={runSanitize}>{hasProvenance ? "Sanitization blocked" : "Sanitize privacy metadata · 1 unit"}</button>{canVerifyC2pa && <button className="secondary" disabled={c2paBusy} onClick={runC2paVerification}>{c2paBusy ? "Verifying…" : "Verify Content Credentials"}</button>}{cleaned && <button className="ghost" onClick={downloadCleaned}>Download cleaned copy</button>}{receipt && originalHash && <button className="ghost" onClick={downloadReceipt}>Export JSON receipt</button>}</div>{receipt?.capabilities.sanitize && <TurnstileWidget action="account" onToken={onChallenge} resetKey={challengeReset} />}
      <div className="trust-note"><span className="status-dot"/><div><strong>Inspection stays in your browser.</strong><p>Billable sanitation uses ephemeral server memory, is re-verified after return, and does not intentionally persist file bytes or filenames.</p></div></div>{billingNote && <div className="success-card">{billingNote}</div>}{error && <div className="error-card">{error}</div>}
    </div><div className="panel file-receipt-panel" aria-label="Verification receipt"><div className="panel-heading"><div><p className="eyebrow">Verification receipt</p><h2>{receipt ? `${receipt.summary.total} metadata finding${receipt.summary.total === 1 ? "" : "s"}` : "Ready to inspect"}</h2></div>{receipt && <span className={`score ${receipt.summary.provenance ? "warn" : "ok"}`}>{receipt.summary.provenance ? "Provenance" : "Inspected"}</span>}</div>
      {!receipt ? <div className="empty-state compact"><div><span className="empty-symbol">◇</span><strong>No file evidence yet</strong><p>Choose a supported file to reveal metadata categories, hashes, removal policy and optional Content Credentials verification.</p></div></div> : <><div className="metrics"><Metric label="Privacy metadata" value={receipt.summary.privacyMetadata} /><Metric label="Provenance" value={receipt.summary.provenance} /><Metric label="Safe removals" value={receipt.summary.removableByDefault} /></div><div className="file-meta-line"><span>{receipt.file.format.toUpperCase()}</span><span>{formatBytes(receipt.file.bytes)}</span><span>{receipt.capabilities.sanitize ? "sanitizable" : "inspection only"}</span></div>{originalHash && <div className="hash-display"><span>Original SHA-256</span><code title={originalHash}>{shortHash(originalHash)}</code><button type="button" className="copy" onClick={()=>navigator.clipboard.writeText(originalHash)}>Copy</button></div>}<div className="findings file-findings">{receipt.findings.length === 0 ? <div className="success-card">No tracked metadata was found.</div> : receipt.findings.map((item) => <article className="finding" key={item.id}><div><strong>{item.label}</strong><p>{item.description}</p></div><span className={item.removableByDefault ? "tag-safe" : "tag-review"}>{item.removableByDefault ? "remove" : "preserve"}</span></article>)}</div>{inspectionId&&originalHash&&<div className="receipt-tools"><button className="ghost" type="button" onClick={()=>publishInspection(receipt,originalHash,inspectionId)}>View receipt</button></div>}</>}
      {c2pa && <div className={c2pa.status === "valid" || c2pa.status === "not_present" ? "verification-box c2pa-card" : "notice-card c2pa-card"}><div className="c2pa-title"><strong>Content Credentials</strong><span className={`score ${c2pa.status==="valid"?"ok":"warn"}`}>{formatC2paStatus(c2pa.status)}</span></div><div className="verification-stats"><span>{c2pa.manifestCount} manifest{c2pa.manifestCount === 1 ? "" : "s"}</span><span>{c2pa.validation.length} validation status{c2pa.validation.length === 1 ? "" : "es"}</span></div><p>{c2pa.note}</p>{c2pa.validation.slice(0, 4).map((item) => <p key={`${item.code}-${item.url ?? ""}`}><strong>{item.code}</strong>{item.explanation ? ` · ${item.explanation}` : ""}</p>)}</div>}
      {cleaned && <div className="before-after-metadata"><div className="comparison-head"><strong>Before / after metadata</strong><span>re-verified in browser</span></div><div className="comparison-grid"><div><span className="mono-label">BEFORE</span><dl><div><dt>privacy metadata</dt><dd>{cleaned.before.summary.privacyMetadata}</dd></div><div><dt>provenance</dt><dd>{cleaned.before.summary.provenance}</dd></div><div><dt>hash</dt><dd className="mono-label">{originalHash?shortHash(originalHash):"—"}</dd></div></dl></div><div className="after"><span className="mono-label">AFTER</span><dl><div><dt>privacy metadata</dt><dd>{cleaned.after.summary.privacyMetadata}</dd></div><div><dt>provenance</dt><dd>{cleaned.after.summary.provenance}</dd></div><div><dt>hash</dt><dd className="mono-label">{cleanedHash?shortHash(cleanedHash):"—"}</dd></div></dl></div></div><p>A changed hash is expected when metadata is removed. The receipt separates byte-level change from provenance claims.</p></div>}
      {hasProvenance && <div className="notice-card blocked-card"><strong>Signed provenance protection</strong><p>This file may contain signed provenance. Changing bytes can break cryptographic authenticity information, so sanitation stays blocked until the integrity consequence is explicit.</p></div>}{receipt?.file.format === "pdf" && <div className="notice-card">PDF remains inspection-only. Safe arbitrary rewriting requires a structure-aware writer that preserves cross-reference tables, signatures, forms and attachments.</div>}
    </div></div>
  </section>;
}
function Metric({ label, value }: { label: string; value: number }) { return <div className="metric"><span>{label}</span><strong>{value}</strong></div>; }function formatBytes(bytes: number) { if (bytes < 1024) return `${bytes} B`;if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;return `${(bytes / (1024 * 1024)).toFixed(1)} MB`; }function shortHash(hash: string) { return `${hash.slice(0, 12)}…${hash.slice(-8)}`; }function baseName(name: string) { const index = name.lastIndexOf(".");return index > 0 ? name.slice(0, index) : name; }function formatC2paStatus(status: C2paVerificationReceipt["status"]) { return status.replaceAll("_", " "); }function downloadBlob(blob: Blob, name: string) { const url = URL.createObjectURL(blob);const anchor = document.createElement("a");anchor.href = url;anchor.download = name;anchor.click();setTimeout(() => URL.revokeObjectURL(url), 0); }

import { GUEST_PROMO_CREDITS, SIGNUP_PROMO_CREDITS } from "@/lib/product-contract";
import { createAdminClient } from "@/lib/supabase/admin";
import type { Database, Json } from "@/lib/supabase/database.types";
import { getBillingLimits, getWelcomeCredits } from "./config";
import type { CreditBalance, CreditReservation } from "./types";
import { BillingDomainError } from "./types";

type JsonObject = Record<string, unknown>;
type BillingFunctionName = keyof Database["public"]["Functions"];
type BillingArgs<Name extends BillingFunctionName> = Database["public"]["Functions"][Name]["Args"];
async function rpc<Name extends BillingFunctionName>(name: Name, args: BillingArgs<Name>): Promise<Json> { const supabase=createAdminClient(); const {data,error}=await supabase.rpc(name,args); if(error) throwBillingError(error.message); return data as Json; }
function jsonObject(value: Json): JsonObject { return value!==null&&typeof value==="object"&&!Array.isArray(value)?value as JsonObject:{}; }
function numeric(value: unknown) { return typeof value==="number"?value:Number(value??0); }
function balanceFrom(data: JsonObject): CreditBalance { return {settled:numeric(data.settled),held:numeric(data.held),available:numeric(data.available)}; }
function throwBillingError(message: string): never { if(message.includes("insufficient_credits")) throw new BillingDomainError("insufficient_credits","Not enough credits are available for this operation."); if(message.includes("rate_limited")) throw new BillingDomainError("rate_limited","Too many editing requests were started recently."); if(message.includes("daily_credit_limit")) throw new BillingDomainError("daily_credit_limit","The daily editing-credit safety limit has been reached."); if(message.includes("operation_conflict")) throw new BillingDomainError("operation_conflict","This operation id has already been used."); throw new BillingDomainError("billing_unavailable","Billing backend is unavailable."); }
export async function initializeCreditAccount(userId:string){await rpc("billing_ensure_account",{p_user_id:userId});const welcome=getWelcomeCredits();if(welcome>0)await rpc("billing_grant_credits",{p_user_id:userId,p_credits:welcome,p_kind:"welcome",p_source_key:`welcome:${userId}`,p_metadata:{}});return getCreditBalance(userId);}
export async function grantGuestPromoCredits(userId:string){const data=jsonObject(await rpc("billing_grant_credits",{p_user_id:userId,p_credits:GUEST_PROMO_CREDITS,p_kind:"promo_guest",p_source_key:`promo:guest:${userId}`,p_metadata:{program:"guest_first_clean"}}));return{balance:balanceFrom(data),granted:Boolean(data.granted)};}
export async function claimSignupPromoCredits(userId:string,emailFingerprint:string){const data=jsonObject(await rpc("billing_claim_signup_promo",{p_user_id:userId,p_email_fingerprint:emailFingerprint,p_credits:SIGNUP_PROMO_CREDITS}));return{balance:balanceFrom(data),granted:Boolean(data.granted)};}
export async function getCreditBalance(userId:string){return balanceFrom(jsonObject(await rpc("billing_get_balance",{p_user_id:userId})));}
export async function getAccountHistory(userId:string,limit=100){return rpc("billing_get_account_history",{p_user_id:userId,p_limit:Math.max(1,Math.min(200,limit))});}
export async function getRefundQuote(userId:string,purchaseId:string){return rpc("billing_get_refund_quote",{p_user_id:userId,p_purchase_id:purchaseId});}
export async function recordPurchaseRefund(input:{userId:string;purchaseId:string;refundId:string;credits:number;amount:number;currency:string}){return rpc("billing_record_purchase_refund",{p_user_id:input.userId,p_purchase_id:input.purchaseId,p_refund_id:input.refundId,p_credits:input.credits,p_amount:input.amount,p_currency:input.currency});}
export async function recordPolicyRefund(input:{eventId:string;eventType:string;purchaseId:string;refundId:string;amount:number;currency:string;reason:"country_policy"|"account_deleted"}){return rpc("billing_record_policy_refund",{p_event_id:input.eventId,p_event_type:input.eventType,p_purchase_id:input.purchaseId,p_refund_id:input.refundId,p_amount:input.amount,p_currency:input.currency,p_reason:input.reason});}
export async function reserveCredits(userId:string,operationKey:string,credits:number):Promise<CreditReservation>{const limits=getBillingLimits();const data=jsonObject(await rpc("billing_reserve_credits",{p_user_id:userId,p_operation_key:operationKey,p_credits:credits,p_requests_per_minute:limits.requestsPerMinute,p_credits_per_24h:limits.creditsPer24h,p_ttl_minutes:limits.reservationTtlMinutes}));return{reservationId:String(data.reservation_id),status:String(data.status) as CreditReservation["status"],credits:numeric(data.credits),created:Boolean(data.created),balance:balanceFrom(data)};}
export async function commitReservation(userId:string,reservationId:string){return balanceFrom(jsonObject(await rpc("billing_commit_reservation",{p_user_id:userId,p_reservation_id:reservationId})));}
export async function releaseReservation(userId:string,reservationId:string,reason:string){await rpc("billing_release_reservation",{p_user_id:userId,p_reservation_id:reservationId,p_reason:reason.slice(0,120)});}
export async function expireStaleReservations(limit=200){return rpc("billing_expire_stale_reservations",{p_limit:Math.max(1,Math.min(500,limit))});}
export async function reconcileDeletedSubjects(limit=200){return rpc("billing_reconcile_deleted_subjects",{p_limit:Math.max(1,Math.min(500,limit))});}
export async function getPhase6Status(){return rpc("billing_phase6_status",{});}
export async function prepareAccountDeletion(userId:string){return rpc("billing_prepare_account_deletion",{p_user_id:userId});}
export async function cancelAccountDeletion(userId:string){return rpc("billing_cancel_account_deletion",{p_user_id:userId});}
export async function finalizeAccountDeletion(userId:string){return rpc("billing_finalize_account_deletion",{p_user_id:userId});}
export async function createPendingPurchase(input:{purchaseId:string;userId:string;packId:string;credits:number;priceId:string}){await rpc("billing_create_purchase",{p_purchase_id:input.purchaseId,p_user_id:input.userId,p_pack_id:input.packId,p_credits:input.credits,p_price_id:input.priceId});}
export async function attachCheckoutSession(purchaseId:string,userId:string,sessionId:string){await rpc("billing_attach_checkout_session",{p_purchase_id:purchaseId,p_user_id:userId,p_session_id:sessionId});}
export async function completeCheckoutPurchase(eventId:string,eventType:string,purchaseId:string,sessionId:string){return rpc("billing_complete_purchase",{p_event_id:eventId,p_event_type:eventType,p_purchase_id:purchaseId,p_session_id:sessionId});}
export async function recordCheckoutAmount(input:{purchaseId:string;sessionId:string;amount:number;currency:string}){return rpc("billing_record_checkout_amount",{p_purchase_id:input.purchaseId,p_session_id:input.sessionId,p_amount:input.amount,p_currency:input.currency.toLowerCase()});}
export async function expireCheckoutPurchase(eventId:string,purchaseId:string,sessionId:string){return rpc("billing_expire_purchase",{p_event_id:eventId,p_purchase_id:purchaseId,p_session_id:sessionId});}
export async function linkStripeCustomer(userId:string,customerId:string){return rpc("billing_link_stripe_customer",{p_user_id:userId,p_customer_id:customerId});}
export async function getLinkedStripeCustomer(userId:string){const data=jsonObject(await rpc("billing_get_stripe_customer",{p_user_id:userId}));const value=data.stripe_customer_id;return typeof value==="string"&&/^cus_/u.test(value)?value:null;}
export async function markAccountSubscriptionsCanceled(userId:string){return rpc("billing_mark_account_subscriptions_canceled",{p_user_id:userId});}
export async function upsertSubscription(input:{eventId:string;eventType:string;userId:string;customerId:string;subscriptionId:string;priceId:string;planId:string;status:string;periodStart:string|null;periodEnd:string|null;cancelAtPeriodEnd:boolean;credits:number}){return rpc("billing_upsert_subscription",{p_event_id:input.eventId,p_event_type:input.eventType,p_user_id:input.userId,p_customer_id:input.customerId,p_subscription_id:input.subscriptionId,p_price_id:input.priceId,p_plan_id:input.planId,p_status:input.status,p_period_start:input.periodStart,p_period_end:input.periodEnd,p_cancel_at_period_end:input.cancelAtPeriodEnd,p_credits:input.credits});}
export async function grantSubscriptionInvoice(input:{eventId:string;eventType:string;invoiceId:string;customerId:string;subscriptionId:string;priceId:string;planId:string;quantity:number;credits:number;periodStart:string|null;periodEnd:string|null;}){return rpc("billing_grant_subscription_invoice",{p_event_id:input.eventId,p_event_type:input.eventType,p_invoice_id:input.invoiceId,p_customer_id:input.customerId,p_subscription_id:input.subscriptionId,p_price_id:input.priceId,p_plan_id:input.planId,p_quantity:input.quantity,p_credits:input.credits,p_period_start:input.periodStart,p_period_end:input.periodEnd});}
export async function recordSubscriptionInvoiceAmount(input:{invoiceId:string;amount:number;currency:string}){return rpc("billing_record_subscription_invoice_amount",{p_invoice_id:input.invoiceId,p_amount:input.amount,p_currency:input.currency.toLowerCase()});}
